    transformedData() {
      const excludedKeys = ["organization_id", "employee_name", "month_year", "month", "payslip_created_on", "email_id", "year", "payslip_id"];
      const result = {};
      for (const [key, value] of Object.entries(this.rowInfo)) {
        if (!excludedKeys.includes(key)) {
          const label = this.transformKeyToLabel(key);
          result[label] = value;
        }
      }
      return result;
    }
  },
  watch: {
    payslipadmin: {
