      immediate: true
    }
  },
  methods: {
    close_dialog() {
      this.$emit("clicked", 0);
    },
    transformKeyToLabel(key) {
      return key.split("_").map(word => word.charAt(0).toUpperCase() + word.slice(1)).join(" ");
    }
  }
};
